// Persistent workspace for Direction. Team and client portals are still previews.
const StudioCloud={mode:'direction',user:null,loaded:false,busy:false,revision:null,last:'',timer:null,blocked:false,assetCache:new Map(),assetPromises:new Map(),pendingLogin:false};
const studioOriginalRender=render;
function studioSnapshot(){return {schemaVersion:1,people,clients,projectRecords,contents,retainerMonths,payrollStatuses,expenseRecords,flowAccounts,flowRecords,flowAccountId,internalNotifications,nextNotificationId,calendarEvents,nextCalendarId}}
function studioApply(s){if(s.schemaVersion!==1||!Array.isArray(s.clients)||!Array.isArray(s.people))throw Error('El formato guardado no es compatible. No se modificó la base de datos.');people=s.people;clients=s.clients;projectRecords=s.projectRecords||[];contents=s.contents||{};retainerMonths=s.retainerMonths||{};payrollStatuses=s.payrollStatuses||{};expenseRecords=s.expenseRecords||[];flowAccounts=s.flowAccounts||flowAccounts;flowRecords=s.flowRecords||[];flowAccountId=s.flowAccountId||1;internalNotifications=s.internalNotifications||[];nextNotificationId=s.nextNotificationId||1;calendarEvents=s.calendarEvents||[];nextCalendarId=s.nextCalendarId||1;selected=0;page='Vista General'}
function studioStatus(text,error=false){const e=document.getElementById('cloudstatus');if(e){e.textContent=text;e.classList.toggle('cloud-error',error)}StudioCloud.error=error}
function studioAccountBar(){const h=document.querySelector('header>div');if(!document.getElementById('cloudstatus'))h.insertAdjacentHTML('afterbegin','<button id="cloudstatus" onclick="studioFlush()">Conectado</button><button onclick="studioLogout()">Cerrar sesión</button>');const demo=document.querySelector('header .demo');if(demo)demo.textContent=(StudioCloud.mode==='team'?'Colaborador':'Dirección')+' · Supabase';}
render=function(){if(!StudioCloud.loaded)return;if(StudioCloud.mode==='team')studioTeamRender();else studioOriginalRender();studioAccountBar();studioSchedule()};
function studioGate(message=''){StudioCloud.loaded=false;document.body.classList.add('studio-locked');const gate=document.getElementById('studiologin');gate.hidden=false;gate.innerHTML=`<div class="studio-loginbox"><img src="assets/logo.png" alt="Clandestino Studio"><div class="eyebrow">WORKSPACE / CLANDESTINO</div><h1>Iniciar sesión</h1><p>Ingresa con tu cuenta del estudio.</p><form onsubmit="studioLogin(event)"><label>Correo<input name="email" type="email" autocomplete="username" placeholder="tu@correo.com" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><p id="studioauthmessage" role="status">${esc(message)}</p><button class="primary wide">Entrar</button></form><details><summary>Primer acceso</summary><p>Crea el usuario direccion@example.com desde Supabase → Authentication → Users → Add user. Elige tu contraseña allí y confirma el correo. La cuenta de Supabase y el usuario de esta app son distintos.</p><p>Si eres colaborador, usa el correo de invitación para activar tu cuenta. Solicita a Dirección reenviar el enlace si venció.</p></details></div>`;}
async function studioLogin(event){event.preventDefault();if(StudioCloud.pendingLogin)return;StudioCloud.pendingLogin=true;const f=new FormData(event.target),button=event.target.querySelector('button'),msg=document.getElementById('studioauthmessage');button.disabled=true;button.textContent='Entrando…';msg.textContent='';try{const {data,error}=await studioBackend.auth.signInWithPassword({email:String(f.get('email')).trim(),password:String(f.get('password'))});if(error)throw error;await studioLoad(data.user)}catch(e){if(document.getElementById('studioauthmessage'))document.getElementById('studioauthmessage').textContent=e.code==='invalid_credentials'?'Correo o contraseña incorrectos. Si es tu primer acceso, crea el usuario en Supabase.':e.code==='email_not_confirmed'?'Confirma tu correo antes de entrar.':e.message||'No se pudo iniciar sesión.'}finally{StudioCloud.pendingLogin=false;button.disabled=false;button.textContent='Entrar'}}
async function studioLoad(user){StudioCloud.user=user;const {data:operator,error:opError}=await studioBackend.from('studio_operators').select('role').eq('email',user.email.toLowerCase()).maybeSingle();if(opError)throw Error('No se pudo verificar tu acceso. Intenta de nuevo.');if(!operator)return studioLoadTeam(user);StudioCloud.mode='direction';studioRefreshInvites();const {data,error}=await studioBackend.from('studio_state').select('payload,revision').eq('id','clandestino').maybeSingle();if(error)throw Error('No se pudo cargar el espacio. No se guardarán cambios hasta recuperar la conexión.');StudioCloud.blocked=false;StudioCloud.error=false;if(data){const hydrated=await studioHydrate(data.payload);studioApply(hydrated);StudioCloud.revision=data.revision;StudioCloud.last=JSON.stringify(studioSnapshot());studioUnlock();}else studioFirstRun();}
function studioFirstRun(){document.getElementById('studiologin').innerHTML=`<div class="studio-loginbox"><img src="assets/logo.png" alt="Clandestino Studio"><h1>Tu espacio está listo</h1><p>La base de datos está vacía. Elige cómo quieres empezar.</p><button class="primary wide" onclick="studioInitialize(false)">Empezar vacío</button><p class="hint">Los registros existentes se cargan desde Supabase. No se importa información del prototipo automáticamente.</p><p id="studioinitmessage" role="status"></p><button onclick="studioLogout()">Cerrar sesión</button></div>`;}
async function studioInitialize(useExamples){if(StudioCloud.busy)return;if(!useExamples)studioApply({schemaVersion:1,people:[],clients:[],flowAccounts:[{id:'cash',name:'Efectivo',kind:'cash'},{id:'bbva',name:'BBVA FISCAL',kind:'bank'},{id:'mp',name:'MERCADO PAGO',kind:'bank'}]});StudioCloud.loaded=true;StudioCloud.last='';try{await studioFlush(true);studioUnlock()}catch(e){StudioCloud.loaded=false;document.getElementById('studioinitmessage').textContent=e.message}}
function studioUnlock(){document.body.classList.remove('studio-locked');document.getElementById('studiologin').hidden=true;StudioCloud.loaded=true;if(StudioCloud.mode==='team')studioTeamRender();else studioOriginalRender();studioAccountBar();studioStatus('Guardado en Supabase');}
function studioSchedule(){if(!StudioCloud.loaded||StudioCloud.blocked)return;const raw=JSON.stringify(studioSnapshot());if(raw===StudioCloud.last)return;studioStatus('Cambios pendientes');clearTimeout(StudioCloud.timer);StudioCloud.timer=setTimeout(()=>studioFlush().catch(()=>{}),1200)}
async function studioEncode(v){if(typeof v==='string'&&(v.startsWith('blob:')||/^data:(image|video)\//.test(v))){if(StudioCloud.assetCache.has(v))return {__studioAsset:StudioCloud.assetCache.get(v)};if(!StudioCloud.assetPromises.has(v))StudioCloud.assetPromises.set(v,(async()=>{const response=await fetch(v);if(!response.ok)throw Error('No se pudo recuperar un archivo para guardarlo.');const blob=await response.blob();let path;if(StudioCloud.mode==='team')path=await studioTeamUpload(blob);else {path='clandestino/'+crypto.randomUUID();const {error}=await studioBackend.storage.from('studio-private').upload(path,blob,{contentType:blob.type,upsert:false});if(error)throw Error('No se pudo guardar un archivo: '+error.message);}StudioCloud.assetCache.set(v,path);return path})());try{return {__studioAsset:await StudioCloud.assetPromises.get(v)}}catch(e){StudioCloud.assetPromises.delete(v);throw e}}if(Array.isArray(v)){const out=[];for(const item of v)out.push(await studioEncode(item));return out}if(v&&typeof v==='object'){const out={};for(const [k,item]of Object.entries(v))out[k]=await studioEncode(item);return out}return v}
async function studioHydrate(v){if(v&&typeof v==='object'&&!Array.isArray(v)&&typeof v.__studioAsset==='string'){const path=v.__studioAsset;if(!path.startsWith('clandestino/'))throw Error('Referencia de archivo inválida.');if(!StudioCloud.assetPromises.has(path))StudioCloud.assetPromises.set(path,(async()=>{const {data,error}=await studioBackend.storage.from('studio-private').download(path);if(error)throw Error('No se pudo recuperar un archivo guardado. Intenta de nuevo antes de editar.');const url=URL.createObjectURL(data);StudioCloud.assetCache.set(url,path);return url})());return await StudioCloud.assetPromises.get(path)}if(Array.isArray(v)){const out=[];for(const item of v)out.push(await studioHydrate(item));return out}if(v&&typeof v==='object'){const out={};for(const[k,item]of Object.entries(v))out[k]=await studioHydrate(item);return out}return v}
async function studioFlush(force=false){clearTimeout(StudioCloud.timer);if(!StudioCloud.loaded||!StudioCloud.user)return;if(StudioCloud.blocked)throw Error('Hay cambios desde otra ventana. Recarga para ver la versión más reciente.');if(StudioCloud.busy){StudioCloud.again=true;return}const raw=JSON.stringify(studioSnapshot());if(!force&&raw===StudioCloud.last)return;StudioCloud.busy=true;studioStatus('Guardando…');try{const payload=await studioEncode(JSON.parse(raw));const revision=(StudioCloud.revision||0)+1;const row={id:'clandestino',schema_version:1,payload,revision,updated_at:new Date().toISOString()};let result;if(StudioCloud.mode==='team')result=await studioTeamSave(raw);else if(StudioCloud.revision===null)result=await studioBackend.from('studio_state').insert(row).select('revision').single();else result=await studioBackend.from('studio_state').update(row).eq('id','clandestino').eq('revision',StudioCloud.revision).select('revision').maybeSingle();if(result.error)throw result.error;if(!result.data){StudioCloud.blocked=true;throw Error('Otra ventana guardó cambios. Conserva esta pestaña abierta y recarga la otra para revisar antes de continuar.');}StudioCloud.revision=result.data.revision;StudioCloud.last=raw;studioStatus('Guardado en Supabase')}catch(e){if(e.code==='23505')StudioCloud.blocked=true;studioStatus(StudioCloud.blocked?'Conflicto entre ventanas · No guardado':'Sin guardar · Pulsa para reintentar',true);if(force)throw e;toast('No se guardaron los cambios. Mantén esta pestaña abierta.');throw e}finally{StudioCloud.busy=false;if(StudioCloud.again){StudioCloud.again=false;studioSchedule()}else if(!StudioCloud.error)studioSchedule()}}
async function studioLogout(){try{if(StudioCloud.loaded){if(StudioCloud.busy)return toast('Espera a que termine el guardado.');await studioFlush();}const {error}=await studioBackend.auth.signOut();if(error)throw error;location.reload()}catch(e){toast('No se cerró la sesión: guarda los cambios pendientes antes de salir.')}}
async function studioBoot(){studioGate('Conectando…');try{const {data,error}=await studioBackend.auth.getUser();if(error||!data.user){studioGate();return}if(window.studioActivationRequested){StudioCloud.user=data.user;studioPasswordForm();return}await studioLoad(data.user)}catch(e){studioGate(e.message)}studioBackend.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'&&StudioCloud.loaded)studioGate('La sesión terminó. Inicia sesión nuevamente.');});}
for(const event of ['input','change','click'])document.addEventListener(event,()=>{if(StudioCloud.loaded)setTimeout(studioSchedule,0)});
window.addEventListener('beforeunload',event=>{if(StudioCloud.loaded&&(StudioCloud.busy||JSON.stringify(studioSnapshot())!==StudioCloud.last)){event.preventDefault();event.returnValue='';}});
studioBoot();
